import { existsSync } from 'node:fs'
import { expect, it } from 'vitest'
import { validateTaskPolicy } from '../src/task-policy.ts'

// Generated by scripts/build-plugin.mjs; absent before the first build.
const generated = new URL('../lib/typert.host.js', import.meta.url)

interface Codec { create(): { safeParse(value: unknown): { success: boolean; data?: { taskPolicy?: unknown } } } }
interface Invocation { namespace: string; method: string; parameters: { codec: Codec }[] }

it.skipIf(!existsSync(generated))('Remote send codec keeps unknown policy keys so the validator fails closed', async () => {
  const { TYPERT } = await import(generated.href) as { TYPERT: { invocations: Invocation[] } }
  const send = TYPERT.invocations.find(item => item.namespace === 'bots' && item.method === 'send')
  const schema = send!.parameters[0]!.codec.create()
  const decode = (taskPolicy: unknown) => {
    const result = schema.safeParse({ roomId: 'room', text: 'hi', taskPolicy })
    return result.success ? { policy: result.data!.taskPolicy } : undefined
  }
  // A typo must reach the validator instead of being stripped into an unrestricted {}.
  expect(decode({ fileMod: 'read-only' })).toEqual({ policy: { fileMod: 'read-only' } })
  expect(() => validateTaskPolicy(decode({ fileMod: 'read-only' })!.policy)).toThrow('Invalid task policy')
  expect(() => validateTaskPolicy(decode({ fileMode: 'read-only', extra: { nested: [1] } })!.policy)).toThrow('Invalid task policy')
  const exact = { fileMode: 'read-only', toolMode: 'allow', tools: ['search_chat', 'read_chat'] }
  expect(validateTaskPolicy(decode(exact)!.policy)).toEqual(exact)
  expect(validateTaskPolicy(decode({ toolMode: 'none', tools: [] })!.policy)).toEqual({ toolMode: 'none', tools: [] })
  expect(decode(undefined)).toEqual({ policy: undefined })
  expect(decode({ fileMode: 'bogus' })).toBeUndefined()
  expect(decode({ toolMode: 'allow', tools: 'search_chat' })).toBeUndefined()
})
